#!/usr/bin/env bash
# Generated by fem-client. Python is managed only through uv (D20); engines run as containers.
set -euo pipefail
cd "$(dirname "$0")"
echo '== geometry and mesh (gmsh)'
uv run --no-project --with 'gmsh==4.13.1' python geometry.py
echo '== mesh conversion to msh (meshlane) and round-trip check'
uv run --no-project --with 'meshlane' --with numpy python convert_mesh.py msh
echo '== FEniCSx'
podman run --rm -v "$PWD":/work:Z -w /work ghcr.io/jorgensd/dolfinx_mpc:v0.11.0 python3 job_fenicsx.py
test -f results.json && echo '== done'
